    "tagline": $fromAI('tagline', 'Courte phrase marketing accrocheuse en français, 4 à 6 mots maximum, adaptée au produit') ,
"tagline_color":  $fromAI('tagline_color', 'Nom de couleur anglais ou code hex, choisi pour contraster avec la scene')
  }
}}

parameters.jsCode:
const raw = $json.output || "";
const match = raw.match(/\/data\/media\/outputs\/[^\s`"]+\.(jpg|jpeg|png)/i);

if (!match) {
  throw new Error("Impossible d'extraire un chemin d'image valide depuis la sortie de l'agent: " + raw);
}

return [
  {
    json: {
      output: match[0]
    }
  }
];

